BEGIN;
CREATE TABLE predictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cio_decision_id uuid NOT NULL,prediction_key text NOT NULL,prediction_type text NOT NULL,direction text NOT NULL,horizon text NOT NULL,statement text NOT NULL,confidence numeric,data_as_of_time timestamptz NOT NULL,prediction_time timestamptz NOT NULL,status text NOT NULL,evidence_ids jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT predictions_decision_fkey FOREIGN KEY(cio_decision_id) REFERENCES cio_decisions(id) ON DELETE RESTRICT,CONSTRAINT predictions_unique UNIQUE(cio_decision_id,prediction_key),CONSTRAINT predictions_type_check CHECK(prediction_type IN ('MARKET_DIRECTION','MACRO_DIRECTION','RISK_CHANGE','REGIME_CHANGE','DIVERGENCE_CHANGE','OTHER')),CONSTRAINT predictions_direction_check CHECK(direction IN ('POSITIVE','NEUTRAL','NEGATIVE','UP','DOWN','UNCHANGED','UNKNOWN')),CONSTRAINT predictions_horizon_check CHECK(horizon IN ('1D','5D','20D','1M','3M')));
CREATE TABLE prediction_targets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),prediction_id uuid NOT NULL,target_type text NOT NULL,asset_id uuid,economic_series_id uuid,metric text NOT NULL,baseline_value numeric,baseline_time timestamptz,evaluation_time timestamptz NOT NULL,threshold_config jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT prediction_targets_prediction_fkey FOREIGN KEY(prediction_id) REFERENCES predictions(id) ON DELETE RESTRICT,CONSTRAINT prediction_targets_asset_fkey FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE RESTRICT,CONSTRAINT prediction_targets_series_fkey FOREIGN KEY(economic_series_id) REFERENCES economic_series(id) ON DELETE RESTRICT);
CREATE TABLE prediction_outcomes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),prediction_id uuid NOT NULL,evaluated_at timestamptz NOT NULL,actual_value numeric,actual_direction text,result_status text NOT NULL,evaluation_version text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT prediction_outcomes_prediction_fkey FOREIGN KEY(prediction_id) REFERENCES predictions(id) ON DELETE RESTRICT,CONSTRAINT prediction_outcomes_unique UNIQUE(prediction_id,evaluation_version,evaluated_at),CONSTRAINT prediction_outcomes_status_check CHECK(result_status IN ('PENDING','CORRECT','INCORRECT','MIXED','UNRESOLVED','INSUFFICIENT_DATA')));
CREATE INDEX predictions_decision_idx ON predictions(cio_decision_id);CREATE INDEX predictions_type_time_idx ON predictions(prediction_type,prediction_time DESC);CREATE INDEX predictions_status_horizon_idx ON predictions(status,horizon);CREATE INDEX prediction_targets_prediction_idx ON prediction_targets(prediction_id);CREATE INDEX prediction_targets_evaluation_idx ON prediction_targets(evaluation_time);CREATE INDEX prediction_outcomes_prediction_idx ON prediction_outcomes(prediction_id);CREATE INDEX prediction_outcomes_status_time_idx ON prediction_outcomes(result_status,evaluated_at DESC);COMMIT;
